// The Fishing view: how much food is in Cobscook Bay in each two-month season.
//
// Every number is the whole amount in the bay before anyone fishes: no cutoffs and no fishing
// method yet. Pure functions first (the tests run them in Node), then createFishing(), which wires
// the controls in the browser. Numbers come from data/fishing.js (generated by
// tools/fishing_model.py); words, colors and species notes from data/fishing-notes.js.
//
// The view is one table: a row per species, a column per season. Tapping a season sorts the rows
// by it, most to least. "Show" picks calories or pounds; "Numbers" picks amounts, each species'
// share of the season (columns), or each season as a % of the species' own best season (rows).
// Tapping a species opens its notes under its row.
//
// The Netting view (renderNetting(), createFishing(panel, { mode: "net" })) is the same table cut
// down to the species you can net (NET_GEAR) that have a season marked as a target. Both views
// share the saved state, so a target marked in one shows in the other.

import { SEASONS, SPECIES, ADULT_KCAL_YEAR, HERRING_CATCH } from "../data/fishing.js";
import {
  FISH_PAGE, SPECIES_COLORS, OTHER_COLOR, MEASURES, NUMBER_VIEWS, CONFIDENCE, PROFILES, HERRING_METHODS, HERRING_CATCH_NOTE,
  METHOD, FISH_NOTES, SEAWEED, FISH_SOURCES, PHOTOS, PHOTO_LICENSES, NET_PAGE, NET_GEAR, NET_FINDINGS, NET_STUDIES,
} from "../data/fishing-notes.js";
import { esc } from "./geo.js";

export const DEFAULT_STATE = { measure: "kcal", view: "amount", picks: {} };

// Targets: the cells Brett has marked green, as { speciesId: [season numbers] }. Anything that
// isn't a known species or season is dropped, so old or hand-edited saves can't break the table.
export function cleanPicks(raw, list = SPECIES, seasons = SEASONS) {
  const out = {};
  if (!raw || typeof raw !== "object") return out;
  for (const sp of list) {
    const bs = Array.isArray(raw[sp.id]) ? raw[sp.id] : [];
    const ok = [...new Set(bs.filter((b) => Number.isInteger(b) && b >= 0 && b < seasons.length))].sort((x, y) => x - y);
    if (ok.length) out[sp.id] = ok;
  }
  return out;
}
export const isPicked = (picks, id, b) => Boolean(picks && picks[id] && picks[id].includes(b));
export function togglePick(picks, id, b) {
  const next = { ...picks };
  const bs = new Set(next[id] || []);
  if (bs.has(b)) bs.delete(b); else bs.add(b);
  if (bs.size) next[id] = [...bs].sort((x, y) => x - y); else delete next[id];
  return next;
}
// The Netting rows: species you can net with at least one season marked as a target.
export const netRows = (picks, list = SPECIES, gear = NET_GEAR) => list.filter((sp) => gear[sp.id] && picks && picks[sp.id] && picks[sp.id].length);

// One season's total over the target cells only (null counts as nothing).
export function targetTotal(list, picks, measure, b) {
  return list.reduce((sum, sp) => sum + (isPicked(picks, sp.id, b) ? valueOf(sp, measure, b) || 0 : 0), 0);
}
export const pickCount = (picks) => Object.values(picks || {}).reduce((n, bs) => n + bs.length, 0);

// "3 targets picked" / "No targets picked yet"
export const pickText = (picks) => {
  const n = pickCount(picks);
  return n ? `${n} target${n === 1 ? "" : "s"} picked` : "No targets picked yet";
};
const STORE = "prep-lt-fish";
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

// ---------- numbers ----------

export const seasonOfDate = (d = new Date()) => Math.floor(d.getMonth() / 2);

// A species has a count if any season has a number. null means "not counted".
export const counted = (sp) => sp.lb.some((v) => v !== null);
export const valueOf = (sp, measure, b) => (measure === "lb" ? sp.lb[b] : sp.kcal[b]);

export function seasonTotal(list, measure, b) {
  return list.reduce((sum, sp) => sum + (valueOf(sp, measure, b) || 0), 0);
}

// Active adults the calories would feed for a year, if every animal were caught.
export const adultsFed = (kcal) => kcal / ADULT_KCAL_YEAR;
// The same, as words: to the nearest 10, as in the doc ("1,960").
export const fedText = (kcal) => commas(Math.round(adultsFed(kcal) / 10) * 10);

// That season's species with a number above zero, biggest first, each with its share (0–100).
export function seasonRanking(list, measure, b) {
  const items = list.map((sp) => ({ sp, value: valueOf(sp, measure, b) })).filter((x) => x.value > 0);
  const total = items.reduce((s, x) => s + x.value, 0);
  return items.map((x) => ({ ...x, share: total ? (100 * x.value) / total : 0 })).sort((a, b2) => b2.value - a.value);
}

// Every species, sorted for one season: most to least, then none counted that season, then not
// counted that season, then species with no count at all. Ties keep the list's order.
export function sortRows(list, measure, b) {
  const group = (sp) => {
    const v = valueOf(sp, measure, b);
    if (v > 0) return 0;
    if (v === 0) return 1;
    return counted(sp) ? 2 : 3;
  };
  return list
    .map((sp, i) => ({ sp, i }))
    .sort((a, c) => group(a.sp) - group(c.sp) || (valueOf(c.sp, measure, b) || 0) - (valueOf(a.sp, measure, b) || 0) || a.i - c.i)
    .map((x) => x.sp);
}

// A species' best season, by the measure (0 when it has no count).
export function bestOf(sp, measure) {
  const vals = (measure === "lb" ? sp.lb : sp.kcal).filter((v) => v !== null);
  return vals.length ? Math.max(...vals) : 0;
}

// What one table cell shows. view: "amount" (millions of calories or thousands of lb),
// "col" (share of the season's total) or "row" (% of the species' own best season).
export function cellText(sp, measure, view, b, list = SPECIES) {
  const v = valueOf(sp, measure, b);
  if (v === null) return "?";
  if (view === "col") {
    const total = seasonTotal(list, measure, b);
    return total ? pct((100 * v) / total) : "0%";
  }
  if (view === "row") {
    const best = bestOf(sp, measure);
    return best ? pct((100 * v) / best) : "0%";
  }
  return measure === "lb" ? thousands(v) : millions(v);
}

// "Herring 72%, mackerel 14%, …, the rest under 1%"
export function rankingText(list, b) {
  const ranked = seasonRanking(list, "kcal", b);
  const big = ranked.filter((x) => x.share >= 1).map((x) => `${x.sp.short} ${Math.round(x.share)}%`);
  if (ranked.length > big.length) big.push("the rest under 1%");
  const text = big.join(", ");
  return text.charAt(0).toUpperCase() + text.slice(1);
}

// The biggest few species as ring slices, the rest folded into "Other".
export function donutSlices(shares, top = 4) {
  const slices = shares.slice(0, top).map(({ sp, value, share }) => ({
    id: sp.id, name: sp.name, color: SPECIES_COLORS[sp.id] || OTHER_COLOR, value, share,
  }));
  const rest = shares.slice(top);
  if (rest.length) {
    slices.push({
      id: "other", name: `Other (${rest.length})`, color: OTHER_COLOR,
      value: rest.reduce((s, x) => s + x.value, 0), share: rest.reduce((s, x) => s + x.share, 0),
    });
  }
  return slices;
}

// The 1947–58 herring record as table rows (two years a row), its average and its months.
export function herringCatch(data = HERRING_CATCH) {
  const half = Math.ceil(data.years.length / 2);
  const rows = data.years.slice(0, half).map(([y, lb], i) => {
    const other = data.years[i + half];
    return [String(y), commas(lb), other ? String(other[0]) : "", other ? commas(other[1]) : ""];
  });
  const average = data.years.reduce((s, [, lb]) => s + lb, 0) / data.years.length;
  const months = data.monthPct.map((v, i) => [MONTHS[i], v]).filter(([, v]) => v >= 0.5).map(([m, v]) => `${m} ${v}%`).join(", ");
  return { rows, average, months };
}

// ---------- words for numbers ----------

// Two significant figures, with commas: 21,250 -> 21,000.
export function round2(n) {
  if (!n) return 0;
  if (Math.abs(n) < 100) return Math.round(n);
  const p = 10 ** (Math.floor(Math.log10(Math.abs(n))) - 1);
  return Math.round(n / p) * p;
}
export const commas = (n) => Math.round(n).toLocaleString("en-US");
export const pct = (x) => (x > 0 && x < 0.5 ? "<1%" : `${Math.round(x)}%`);

// Calories in millions, as in the table: 1,540 · 7.4 · <0.1 · 0 · ? (not counted).
export function millions(n) {
  if (n === null || n === undefined) return "?";
  if (n === 0) return "0";
  const m = n / 1e6;
  if (m < 0.05) return "<0.1";
  return m < 10 ? m.toFixed(1) : commas(m);
}

// Pounds in thousands, as in the table: 3,580 · 2 · <1 · 0 · ?.
export function thousands(n) {
  if (n === null || n === undefined) return "?";
  if (n === 0) return "0";
  return n < 500 ? "<1" : commas(n / 1e3);
}

// For sentences: "2.1 billion calories", "600 million calories".
export function caloriesText(n) {
  if (n >= 1e9) return `${(round2(n) / 1e9).toLocaleString("en-US")} billion calories`;
  if (n >= 1e6) return `${(round2(n) / 1e6).toLocaleString("en-US")} million calories`;
  return `${commas(round2(n))} calories`;
}

// For one species: "3,580,000 lb", "260 lb".
export function poundsText(n) {
  if (n >= 1000) return `${commas(Math.round(n / 1000) * 1000)} lb`;
  return `${commas(round2(n))} lb`;
}

const weightWord = (sp) => (sp.weight === "meat" ? "meat" : "live weight");

// "60% of live weight, 717 calories a pound of meat"
export function meatText(sp, profile = PROFILES[sp.id] || {}) {
  const cal = `${commas(sp.kcalPerLb)} calories a pound of meat`;
  if (sp.weight === "meat") return `Meat only, ${cal}`;
  if (sp.meatShares) {
    // Changes by season (urchin roe): "4.5–8.1% of live weight by season, …"
    const pc = (v) => String(Math.round(v * 1000) / 10);
    return `${pc(Math.min(...sp.meatShares))}–${pc(Math.max(...sp.meatShares))}% of live weight by season, ${cal}`;
  }
  if (sp.meatShare) return `${Math.round(sp.meatShare * 100)}% of live weight, ${cal}`;
  return profile.yield ? `${profile.yield}, ${cal}` : cal;
}

// ---------- drawing (HTML strings) ----------

const confChip = (sp) => `<span class="ltf-conf ltf-conf-${sp.confidence}" title="${esc(`How sure: ${sp.confidence} of 5. ${CONFIDENCE[sp.confidence]}`)}">${sp.confidence}</span>`;
const swatch = (sp) => `<span class="ltf-swatch" style="background:${esc(SPECIES_COLORS[sp.id] || OTHER_COLOR)}"></span>`;

// Wikimedia Commons addresses for a picture: the 500 px copy and the file's page (credit and license).
export function photoSrc(ph) {
  const f = encodeURIComponent(ph.file);
  return `https://upload.wikimedia.org/wikipedia/commons/thumb/${ph.dir}/${f}/500px-${f}`;
}
export const photoPage = (ph) => `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(ph.file)}`;

// The species' pictures, each with its name and credit. Lazy, so nothing loads until the notes open.
export function photosHtml(sp, photos = PHOTOS) {
  const list = photos[sp.id] || [];
  if (!list.length) return "";
  const figs = list.map((ph) => {
    const lic = PHOTO_LICENSES[ph.license];
    const licHtml = lic ? `<a href="${esc(lic)}" target="_blank" rel="noopener">${esc(ph.license)}</a>` : esc(ph.license.toLowerCase());
    return `<figure class="ltf-photo"><a href="${esc(photoPage(ph))}" target="_blank" rel="noopener"><img src="${esc(photoSrc(ph))}" width="${ph.w}" height="${ph.h}" alt="${esc(ph.label)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></a>`
      + `<figcaption><b>${esc(ph.label)}</b>${ph.drawing ? " (drawing)" : ""}. ${esc(ph.by)}, ${licHtml}</figcaption></figure>`;
  });
  return `<div class="ltf-photos">${figs.join("")}</div>`;
}

function profileHtml(sp, b, seasons = SEASONS) {
  const p = PROFILES[sp.id] || {};
  const label = seasons[b].label;
  const has = sp.lb[b] !== null;
  const rows = [
    has ? [`Calories in ${label}`, sp.kcal[b] ? `${millions(sp.kcal[b])} million` : "None counted"] : null,
    has ? [`Pounds in ${label}`, sp.lb[b] ? `${poundsText(sp.lb[b])} (${weightWord(sp)})` : "None counted"] : null,
    !has && counted(sp) ? [label, "Not counted this season"] : null,
    ["Meat", meatText(sp, p)],
    ["Where the number comes from", sp.source],
    ["How sure", `${sp.confidence} of 5: ${CONFIDENCE[sp.confidence]}`],
    ["Best season", p.best], ["Size", p.size], ["Gear", p.gear], ["Rules today", p.rules], ["Notes", p.safety],
  ].filter((r) => r && r[1]);
  return photosHtml(sp) + `<dl class="ltf-profile">${rows.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join("")}</dl>`;
}

const CAPTIONS = {
  amount: {
    kcal: "Calories in the bay, in millions.",
    lb: "Pounds in the bay, in thousands (live weight; scallops are meat). Pounds aren't added up, since meat and shell weigh so differently.",
  },
  col: {
    kcal: "Each species' share of that season's calories.",
    lb: "Each species' share of that season's pounds (rough: scallops are meat, the rest live weight).",
  },
  row: {
    kcal: "Each season as a % of the species' own best season, by calories (100% = its best). Seasons aren't added up.",
    lb: "Each season as a % of the species' own best season, by pounds (100% = its best). Seasons aren't added up.",
  },
};

// The table. open = ids of species whose notes are showing. list is every species (it sets the
// season totals); opts.rows draws only some of them (the Netting view), opts.idPrefix keeps the
// notes rows' ids apart from the other view's, opts.sub puts a line under each name, and
// opts.foot "targets" totals only the target cells.
export function drawTable(state, season, open = new Set(), list = SPECIES, seasons = SEASONS, opts = {}) {
  const { rows: shown = list, idPrefix = "ltf-d-", sub = null } = opts;
  const measure = state.measure === "lb" ? "lb" : "kcal";
  const view = ["col", "row"].includes(state.view) ? state.view : "amount";
  const cols = seasons.length + 2;
  const heads = seasons.map((s, b) => `<th scope="col"${b === season ? ' class="is-on" aria-sort="descending"' : ""}><button type="button" data-season="${b}" aria-pressed="${b === season}" title="Sort by ${esc(s.long)}">${esc(s.label.replace("–", "–​"))}</button></th>`).join("");

  const rows = sortRows(shown, measure, season).map((sp) => {
    const best = bestOf(sp, measure);
    const known = (measure === "lb" ? sp.lb : sp.kcal).filter((v) => v !== null);
    const flat = known.every((v) => v === best); // same every season: no best to mark
    const cells = seasons.map((_, b) => {
      const v = valueOf(sp, measure, b);
      const picked = isPicked(state.picks, sp.id, b);
      const cls = ["ltf-pickcell", b === season ? "is-on" : "", v === null ? "is-unknown" : "", view === "row" && v && v === best && !flat ? "is-best" : "", picked ? "is-picked" : ""].filter(Boolean).join(" ");
      return `<td class="${cls}"><button type="button" class="ltf-pick" data-pick="${esc(sp.id)}" data-b="${b}" aria-pressed="${picked}" title="${picked ? "Unmark" : "Mark"} ${esc(sp.short)} as a target in ${esc(seasons[b].long)}">${esc(cellText(sp, measure, view, b, list))}</button></td>`;
    }).join("");
    const name = measure === "lb" && sp.weight === "meat" ? `${sp.name} (meat)` : sp.name;
    const isOpen = open.has(sp.id);
    const did = `${idPrefix}${sp.id}`;
    const subLine = sub && sub[sp.id] ? `<span class="ltf-sp-sub">${esc(sub[sp.id])}</span>` : "";
    return `<tr class="ltf-tbl-row${isOpen ? " is-open" : ""}"><th scope="row"><button type="button" class="ltf-sp" data-sp="${esc(sp.id)}" aria-expanded="${isOpen}" aria-controls="${esc(did)}">${swatch(sp)}${esc(name)}</button>${subLine}</th>${cells}<td class="ltf-tbl-conf">${confChip(sp)}</td></tr>
          <tr class="ltf-tbl-detail" id="${esc(did)}"${isOpen ? "" : " hidden"}><td colspan="${cols}">${profileHtml(sp, season, seasons)}</td></tr>`;
  }).join("");

  const footCell = (text, b) => `<td${b === season ? ' class="is-on"' : ""}>${esc(text)}</td>`;
  let foot = "";
  if (opts.foot === "targets") {
    if (view === "amount" && measure === "kcal") {
      const totals = seasons.map((_, b) => targetTotal(shown, state.picks, "kcal", b));
      foot = `
          <tr><th scope="row">Your netting targets</th>${totals.map((t, b) => footCell(t ? millions(t) : "–", b)).join("")}<td></td></tr>
          <tr><th scope="row">Active adults fed a year, if all were caught</th>${totals.map((t, b) => footCell(t ? fedText(t) : "–", b)).join("")}<td></td></tr>`;
    }
  } else if (view === "amount" && measure === "kcal") {
    foot = `
          <tr><th scope="row">Total</th>${seasons.map((_, b) => footCell(millions(seasonTotal(list, "kcal", b)), b)).join("")}<td></td></tr>
          <tr><th scope="row">Active adults fed a year, if all were caught</th>${seasons.map((_, b) => footCell(fedText(seasonTotal(list, "kcal", b)), b)).join("")}<td></td></tr>`;
  } else if (view === "col") {
    foot = `
          <tr><th scope="row">Total</th>${seasons.map((_, b) => footCell(seasonTotal(list, measure, b) ? "100%" : "–", b)).join("")}<td></td></tr>`;
  } else if (view === "row" && measure === "kcal") {
    const totals = seasons.map((_, b) => seasonTotal(list, "kcal", b));
    const max = Math.max(...totals);
    foot = `
          <tr><th scope="row">All species</th>${totals.map((t, b) => footCell(max ? pct((100 * t) / max) : "–", b)).join("")}<td></td></tr>`;
  }

  return `
    <div class="table-scroll ltf-tbl-wrap">
      <table class="ltf-tbl">
        <caption>${esc(CAPTIONS[view][measure])} ? = not counted. "Sure" is how sure each number is, 1 to 5.</caption>
        <thead><tr><th scope="col">Species</th>${heads}<th scope="col" class="ltf-tbl-conf">Sure</th></tr></thead>
        <tbody>${rows}</tbody>${foot ? `
        <tfoot>${foot}
        </tfoot>` : ""}
      </table>
    </div>`;
}

function herringHtml() {
  const hc = herringCatch();
  return `
      <details class="ltm-notes">
        <summary>Herring: three ways to measure it</summary>
        <p>${esc(HERRING_METHODS.lead)}</p>
        <div class="table-scroll"><table class="data ltf-table">
          <thead><tr><th scope="col">Method</th><th scope="col">Herring in the bay</th><th scope="col">How it was made</th></tr></thead>
          <tbody>${HERRING_METHODS.rows.map((r) => `<tr><th scope="row">${esc(r[0])}</th><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join("")}</tbody>
        </table></div>
        <p class="ltf-hint">${esc(HERRING_METHODS.after)}</p>
      </details>
      <details class="ltm-notes">
        <summary>Herring caught in Cobscook, 1947–58</summary>
        <div class="table-scroll"><table class="data ltf-table ltf-herring">
          <thead><tr><th scope="col">Year</th><th scope="col">Pounds</th><th scope="col">Year</th><th scope="col">Pounds</th></tr></thead>
          <tbody>${hc.rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody>
        </table></div>
        <p class="ltf-hint">Average ${esc(commas(hc.average))} lb a year. By month: ${esc(hc.months)} of the catch. ${esc(HERRING_CATCH_NOTE)}</p>
      </details>`;
}

// The static page: heading, controls, the empty table area, notes.
export function renderFishing(page = FISH_PAGE) {
  const seg = (name, options) => options.map(([v, label], i) => `
          <label class="ltm-seg-item"><input type="radio" name="${name}" value="${esc(v)}"${i === 0 ? " checked" : ""}><span>${esc(label)}</span></label>`).join("");
  const conf = Object.keys(CONFIDENCE).sort((a, b) => b - a).map((k) => `<li><span class="ltf-conf ltf-conf-${esc(k)}">${esc(k)}</span> ${esc(CONFIDENCE[k])}</li>`).join("");
  return `
    <section class="ltf" aria-labelledby="ltf-heading">
      <h2 id="ltf-heading" class="section-title">${esc(page.heading)}</h2>
      <p class="muted ltf-intro">${esc(page.intro)} <span class="ltf-draft">${esc(page.draft)}</span></p>

      <div class="ltf-controls">
        <div class="ltm-group" role="radiogroup" aria-labelledby="ltf-measure-label">
          <span id="ltf-measure-label" class="ltm-label">Show</span>
          <div class="ltm-seg ltf-seg-2">${seg("ltf-measure", Object.entries(MEASURES).map(([k, m]) => [k, m.label]))}</div>
        </div>
        <div class="ltm-group" role="radiogroup" aria-labelledby="ltf-view-label">
          <span id="ltf-view-label" class="ltm-label">Numbers</span>
          <div class="ltm-seg ltf-seg-3">${seg("ltf-view", Object.entries(NUMBER_VIEWS))}</div>
        </div>
      </div>

      <p class="ltf-hint ltf-tbl-hint">Tap a season to sort by it, most to least. Tap a species for its notes. Tap a number to mark it green as a target for that season, and tap it again to unmark it; your targets are kept in this browser. For species that stay all year, like urchins, periwinkles, clams and scallops, each season shows the same animals, so don't add the seasons together.</p>
      <div class="ltf-picks-bar"><span class="ltf-picks-count" data-picks-count aria-live="polite"></span><button type="button" class="btn-link ltf-picks-clear" data-clear-picks hidden>Clear targets</button></div>
      <div class="ltf-chart" data-table></div>

      <details class="ltm-notes" open>
        <summary>Keep in mind</summary>
        <ul>${FISH_NOTES.map((n) => `<li>${esc(n)}</li>`).join("")}</ul>
      </details>${herringHtml()}
      <details class="ltm-notes">
        <summary>Seaweed (not counted above)</summary>
        <div class="table-scroll"><table class="data ltf-table">
          <thead><tr><th scope="col">Seaweed</th><th scope="col">Best time to pick</th><th scope="col">Use</th></tr></thead>
          <tbody>${SEAWEED.map((r) => `<tr>${r.map((c, i) => (i ? `<td>${esc(c)}</td>` : `<th scope="row">${esc(c)}</th>`)).join("")}</tr>`).join("")}</tbody>
        </table></div>
        <p class="ltf-hint">Cut the fronds and leave the base attached so it grows back. Don't pick near sewage outfalls.</p>
      </details>
      <details class="ltm-notes">
        <summary>How these numbers were made</summary>
        <p class="ltf-hint">How sure each number is:</p>
        <ul class="ltf-conf-list">${conf}</ul>
        <ol>${METHOD.map((n) => `<li>${esc(n)}</li>`).join("")}</ol>
      </details>
      <details class="ltm-notes">
        <summary>Sources</summary>
        <ul>${FISH_SOURCES.map(([t, u]) => `<li><a href="${esc(u)}" target="_blank" rel="noopener">${esc(t)}</a></li>`).join("")}</ul>
      </details>
    </section>`;
}

// Under the Netting table: one collapsed section per species in it, "Atlantic herring netting",
// holding what we've found out about netting it (NET_FINDINGS).
export function drawFindings(rows, findings = NET_FINDINGS, page = NET_PAGE) {
  return rows.map((sp) => {
    const items = findings[sp.id] || [];
    const body = items.length ? items.map((p) => `<p>${esc(p)}</p>`).join("") : `<p class="muted">${esc(page.noFindings)}</p>`;
    return `
      <details class="ltm-notes ltn-findings" data-findings-for="${esc(sp.id)}">
        <summary>${esc(`${sp.name} netting`)}</summary>
        ${body}
      </details>`;
  }).join("");
}

// Under the species sections: one collapsed section per fyke net study (NET_STUDIES), with its facts
// as label and text rows, its catch tables and its links. These don't depend on your targets, so
// they're drawn once with the page and stay open while you work the table.
const factRows = (facts) => (facts || []).map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join("");
export function drawStudies(studies = NET_STUDIES) {
  return studies.map((s) => {
    const table = (s.tables || []).map((t) => `
        <div class="ltn-study-tbl-wrap"><table class="ltn-study-tbl">
          <caption>${esc(t.caption)}</caption>
          <thead><tr>${t.head.map((h) => `<th scope="col">${esc(h)}</th>`).join("")}</tr></thead>
          <tbody>${t.rows.map(([name, ...cells]) => `<tr><th scope="row">${esc(name)}</th>${cells.map((c) => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody>
        </table></div>`).join("");
    const links = s.links && s.links.length
      ? `<div><dt>Links</dt><dd><ul>${s.links.map(([title, url]) => `<li><a href="${esc(url)}" target="_blank" rel="noopener">${esc(title)}</a></li>`).join("")}</ul></dd></div>`
      : "";
    const after = factRows(s.after) + links;
    return `
      <details class="ltm-notes ltn-study" data-study="${esc(s.id)}">
        <summary>${esc(s.title)}</summary>
        <p>${esc(s.about)}</p>
        <dl class="ltn-facts">${factRows(s.facts)}</dl>${table}${after ? `
        <dl class="ltn-facts">${after}</dl>` : ""}
      </details>`;
  }).join("");
}

// A YouTube video that plays on the page. youtube-nocookie keeps YouTube's cookies off until it's
// played; loading="lazy" means nothing loads until the Netting tab is shown. The page's referrer is
// left on, since YouTube's player refuses to play without it.
export function videoHtml(video) {
  if (!video || !/^[\w-]{11}$/.test(video.id)) return "";
  const src = `https://www.youtube-nocookie.com/embed/${video.id}?rel=0`;
  return `
      <figure class="ltn-video">
        <div class="ltn-video-frame">
          <iframe src="${esc(src)}" title="${esc(video.title)}" loading="lazy" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
        </div>
        <figcaption>${esc(video.title)}, from ${esc(video.channel)} on YouTube.</figcaption>
      </figure>`;
}

// The Netting view's static page: the video, heading, the same controls (their own radio names), the table area.
export function renderNetting(page = NET_PAGE) {
  const seg = (name, options) => options.map(([v, label], i) => `
          <label class="ltm-seg-item"><input type="radio" name="${name}" value="${esc(v)}"${i === 0 ? " checked" : ""}><span>${esc(label)}</span></label>`).join("");
  return `
    <section class="ltf ltn" aria-labelledby="ltn-heading">${videoHtml(page.video)}
      <h2 id="ltn-heading" class="section-title">${esc(page.heading)}</h2>
      <p class="muted ltf-intro">${esc(page.intro)}</p>

      <div class="ltf-controls">
        <div class="ltm-group" role="radiogroup" aria-labelledby="ltn-measure-label">
          <span id="ltn-measure-label" class="ltm-label">Show</span>
          <div class="ltm-seg ltf-seg-2">${seg("ltn-measure", Object.entries(MEASURES).map(([k, m]) => [k, m.label]))}</div>
        </div>
        <div class="ltm-group" role="radiogroup" aria-labelledby="ltn-view-label">
          <span id="ltn-view-label" class="ltm-label">Numbers</span>
          <div class="ltm-seg ltf-seg-3">${seg("ltn-view", Object.entries(NUMBER_VIEWS))}</div>
        </div>
      </div>

      <p class="ltf-hint ltf-tbl-hint">${esc(page.hint)}</p>
      <div class="ltf-chart" data-table></div>
      <div class="ltn-findings-list" data-findings></div>
      <div class="ltn-studies" data-studies>${drawStudies()}</div>
      <p class="ltf-hint ltn-note">${esc(page.notShown)}</p>
      <p class="ltf-hint ltn-note">${esc(page.more)}</p>
    </section>`;
}

// ---------- browser ----------

function readState() {
  try {
    const s = JSON.parse(localStorage.getItem(STORE) || "{}");
    return {
      measure: MEASURES[s.measure] ? s.measure : DEFAULT_STATE.measure,
      view: NUMBER_VIEWS[s.view] ? s.view : DEFAULT_STATE.view,
      picks: cleanPicks(s.picks),
    };
  } catch { return { ...DEFAULT_STATE, picks: {} }; }
}
function saveState(state) {
  try { localStorage.setItem(STORE, JSON.stringify({ measure: state.measure, view: state.view, picks: state.picks })); } catch { /* private mode */ }
}

// mode "fish" is the full table; mode "net" is the Netting view. The Netting rows are picked when
// the view is shown (refresh()), so a row stays put while you tap its numbers.
export function createFishing(panel, { mode = "fish" } = {}) {
  const net = mode === "net";
  const pre = net ? "ltn" : "ltf";
  let state = readState();
  let season = seasonOfDate();
  const open = new Set();
  const table = panel.querySelector("[data-table]");
  let rowIds = new Set();
  const findingsBox = panel.querySelector("[data-findings]");
  // The findings sections follow the rows, and are drawn only when the rows are picked, so sorting
  // and tapping targets don't close a section you've opened.
  const pickRows = () => {
    rowIds = new Set(netRows(state.picks).map((sp) => sp.id));
    if (findingsBox) findingsBox.innerHTML = drawFindings(SPECIES.filter((sp) => rowIds.has(sp.id)));
  };

  function syncInputs() {
    for (const input of panel.querySelectorAll(`input[name="${pre}-measure"]`)) input.checked = input.value === state.measure;
    for (const input of panel.querySelectorAll(`input[name="${pre}-view"]`)) input.checked = input.value === state.view;
  }

  const count = panel.querySelector("[data-picks-count]");
  const clear = panel.querySelector("[data-clear-picks]");
  function showPicks() {
    if (count) count.textContent = pickText(state.picks);
    if (clear) clear.hidden = !pickCount(state.picks);
  }
  function draw() {
    if (net) {
      const rows = SPECIES.filter((sp) => rowIds.has(sp.id));
      table.innerHTML = rows.length
        ? drawTable(state, season, open, SPECIES, SEASONS, { rows, idPrefix: "ltn-d-", sub: NET_GEAR, foot: "targets" })
        : `<p class="ltn-empty">${esc(NET_PAGE.empty)}</p>`;
    } else {
      table.innerHTML = drawTable(state, season, open);
    }
    showPicks();
  }

  function onChange(e) {
    if (e.target.name === `${pre}-measure`) state.measure = e.target.value;
    else if (e.target.name === `${pre}-view`) state.view = e.target.value;
    else return;
    saveState(state);
    draw();
  }
  function onClick(e) {
    const cell = e.target.closest("[data-pick]");
    if (cell && panel.contains(cell)) {
      const id = cell.dataset.pick;
      const b = Number(cell.dataset.b);
      state.picks = togglePick(state.picks, id, b);
      if (net) {
        // Redraw so the targets total updates; the row stays until the view is shown again.
        saveState(state);
        draw();
        table.querySelector(`[data-pick="${CSS.escape(id)}"][data-b="${b}"]`)?.focus();
        return;
      }
      const on = isPicked(state.picks, id, b);
      cell.setAttribute("aria-pressed", String(on));
      cell.title = `${on ? "Unmark" : "Mark"}${cell.title.replace(/^(Unmark|Mark)/, "")}`;
      cell.closest("td").classList.toggle("is-picked", on);
      saveState(state);
      showPicks();
      return;
    }
    if (e.target.closest("[data-clear-picks]") && panel.contains(e.target)) {
      if (!pickCount(state.picks)) return;
      state.picks = {};
      saveState(state);
      draw();
      return;
    }
    const sp = e.target.closest("[data-sp]");
    if (sp && panel.contains(sp)) {
      const id = sp.dataset.sp;
      const isOpen = !open.has(id);
      if (isOpen) open.add(id); else open.delete(id);
      sp.setAttribute("aria-expanded", String(isOpen));
      sp.closest("tr").classList.toggle("is-open", isOpen);
      const detail = panel.querySelector(`#${pre}-d-${CSS.escape(id)}`);
      if (detail) detail.hidden = !isOpen;
      return;
    }
    const btn = e.target.closest("[data-season]");
    if (!btn || !panel.contains(btn)) return;
    season = Number(btn.dataset.season);
    draw();
    table.querySelector(`[data-season="${season}"]`)?.focus();
  }

  panel.addEventListener("change", onChange);
  panel.addEventListener("click", onClick);
  if (net) pickRows();
  syncInputs();
  draw();

  return {
    // Shown again: the other view may have changed the targets or Show and Numbers.
    refresh() {
      state = readState();
      if (net) pickRows();
      syncInputs();
      draw();
    },
    destroy() {
      panel.removeEventListener("change", onChange);
      panel.removeEventListener("click", onClick);
    },
  };
}
